const rows = $input.all();
let certsList = [];
for (const row of rows) {
  const d = row.json;
  const provider = d['Provider'] || '';
  const name = d['Name of the Certification'] || d['Certification'] || '';
  const date = d['Date/Month of Completion'] || d['Date'] || '';
  if (!name) continue;
  certsList.push(name + (provider ? ' — ' + provider : '') + (date ? ' (' + date + ')' : ''));
}
const certificationsText = certsList.length > 0 ? certsList.map(c => '• ' + c).join('\n') : '';
return [{ json: { certificationsText, hasCertifications: certsList.length > 0 } }];

const rows = $input.all();
let skillsByCategory = {};
let allSkills = [];
for (const row of rows) {
  const data = row.json;
  const category = data['Category'] || data['Skill Category'] || data['Type'] || 'General';
  const skill = data['Skill'] || data['Skill Name'] || data['Name'] || '';
  const level = data['Level'] || data['Proficiency'] || '';
  if (!skill) continue;
  const label = level ? skill + ' (' + level + ')' : skill;
  allSkills.push(label);
  if (!skillsByCategory[category]) skillsByCategory[category] = [];
  skillsByCategory[category].push(label);
}
let skillsText = '';
for (const [cat, skills] of Object.entries(skillsByCategory)) {
  skillsText += '**' + cat + '**: ' + skills.join(', ') + '\n';
}
if (!skillsText) skillsText = 'Python, JavaScript, SQL, REST APIs, Cloud Computing, Data Analysis';
const flatSkills = allSkills.slice(0, 18).join(', ') || skillsText;
return [{ json: { skillsByCategory, skillsText, flatSkills, totalSkills: allSkills.length } }];

const item = $('Filter: Create or Rework (Resume)').item.json;
const company = (item['Company'] || 'Target Company').trim();
const jobTitle = (item['Position - Title'] || 'Professional').trim();
const jobDesc = (item['Position - Description'] || 'Not provided.').trim();
const rowNumber = item['row_number'] || item['rowNumber'] || 2;
const isRework = (item['Resume Status'] || '').trim() === 'Needs Rework';
const reworkNotes = (item['Notes for Resume'] || '').trim();

let skillsText = '';
try { skillsText = $('Compile Skills from Sheet').first().json.skillsText || ''; } catch(e) {}
if (!skillsText) skillsText = 'Python, JavaScript, SQL, REST APIs, Data Analysis';

let certificationsText = '';
try { certificationsText = $('Compile Certifications').first().json.certificationsText || ''; } catch(e) {}

let examplesText = '';
try {
  const exs = $('Query Supabase for Examples').all();
  let n = 1;
  for (const ex of exs) {
    if (ex.json && ex.json.generated_markdown && !ex.json.error) {
      examplesText += '### Reference ' + n + ' — ' + ex.json.job_title + ' @ ' + ex.json.company_name + ':\n' + ex.json.generated_markdown + '\n\n---\n\n';
      n++;
    }
  }
} catch(e) {}

let existingMarkdown = '';
try {
  const drafts = $('Fetch Current Draft (Resume)').all()
    .filter(d => d.json && d.json.generated_markdown && !d.json.error)
    .sort((a, b) => new Date(b.json.created_at) - new Date(a.json.created_at));
  if (drafts.length > 0) existingMarkdown = drafts[0].json.generated_markdown;
} catch(e) {}

let promptText = '';
if (isRework && existingMarkdown) {
  promptText = 'You are an Expert Resume Editor for Sumanto Banerjee.\n\n'
    + 'REWORK MODE: Apply ONLY the specific feedback below to the current resume. '
    + 'Do NOT change any other section. Every other line must remain word-for-word identical.\n\n'
    + 'CURRENT RESUME:\n---\n' + existingMarkdown + '\n---\n\n'
    + 'FEEDBACK TO IMPLEMENT:\n' + reworkNotes + '\n\n'
    + 'Return the COMPLETE updated resume in Markdown with ONLY the above changes applied. No explanations, no commentary.';
} else {
  promptText = 'You are an Expert ATS-Optimized Resume Writer for Sumanto Banerjee.\n\n'
    + 'TARGET ROLE: ' + jobTitle + '\n'
    + 'TARGET COMPANY: ' + company + '\n\n'
    + 'JOB DESCRIPTION:\n' + jobDesc + '\n\n'
    + 'SUMANTO SKILLS (pick the most relevant — do not invent new ones):\n' + skillsText
    + (certificationsText ? '\n\nCERTIFICATIONS (include ALL in the resume):\n' + certificationsText : '')
    + (examplesText ? '\n\nSUMANTO\'S OWN REFERENCE RESUMES (use exact phrasing, bullets, structure as needed):\n' + examplesText : '')
    + '\n\n---\n\n'
    + 'GENERATE a complete ATS-optimized ONE-PAGE resume in Markdown.\n\n'
    + 'STRUCTURE:\n'
    + '# Sumanto Banerjee\n'
    + '[Contact: email | phone | LinkedIn | Location]\n\n'
    + '## Professional Summary\n'
    + '[2-3 sentences mentioning exact role and company. Quantify impact.]\n\n'
    + '## Core Skills\n'
    + '[8-12 bullet points of the most relevant skills from the list]\n\n'
    + '## Professional Experience\n'
    + '[Most relevant roles. Bullets use: Accomplished X, measured by Y, by doing Z. Bold key metrics and tech.]\n\n'
    + '## Education\n'
    + '[Degree, University, Year]\n\n'
    + '## Certifications\n'
    + '[List all certifications from the certifications section above]\n\n'
    + '## Key Projects (only if space permits on one page)\n'
    + '[Brief 2-line descriptions with tech and metrics]\n\n'
    + 'STRICT RULES:\n'
    + '1. ONE PAGE ONLY — ruthlessly cut anything not directly relevant to the JD\n'
    + '2. ATS-FRIENDLY — use bullet lists for skills, avoid tables\n'
    + '3. BOLD key metrics, technologies, and tools\n'
    + '4. Every experience bullet: Google Formula (Accomplished X measured by Y by doing Z)\n'
    + '5. If information is missing — OMIT that section. NO placeholder text whatsoever\n'
    + '6. You may borrow exact phrases and bullets from the reference resumes above\n'
    + '7. Output ONLY the Markdown — no commentary or explanations';
}

return [{ json: { company, jobTitle, jobDesc, rowNumber, isRework, reworkNotes, existingMarkdown, skillsText, certificationsText, promptText, candidateName: 'Sumanto Banerjee' } }];

const md = $json.text || '';
const inp = $('Prepare Resume Inputs').item.json;
const { company, jobTitle, rowNumber, candidateName } = inp;
const fileName = 'Resume - ' + candidateName + ' - ' + company + '.pdf';
function mdToHtml(text) {
  let h = text;
  h = h.replace(/^# (.+)$/gm, '<h1 class="name">$1</h1>');
  h = h.replace(/^## (.+)$/gm, '<h2 class="section-title">$1</h2>');
  h = h.replace(/^### (.+)$/gm, '<h3 class="job-title">$1</h3>');
  h = h.replace(/^---$/gm, '<hr/>');
  h = h.replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>');
  h = h.replace(/\*([^*\n]+)\*/g, '<span class="date">$1</span>');
  h = h.replace(/^- (.+)$/gm, '<li>$1</li>');
  h = h.replace(/(<li>[\s\S]*?<\/li>\n?)+/g, (b) => '<ul>' + b + '</ul>');
  h = h.replace(/^(📧[^\n]+)$/gm, '<p class="contact">$1</p>');
  h = h.replace(/\n\n+/g, '</p><p>');
  h = '<p>' + h + '</p>';
  h = h.replace(/<p>\s*(<h[123]|<hr|<ul)/g, '$1');
  h = h.replace(/(<\/h[123]>|<\/ul>|<hr\/>)\s*<\/p>/g, '$1');
  h = h.replace(/<p>\s*<\/p>/g, '');
  return h;
}
const bodyHtml = mdToHtml(md);
const css = '@page{size:A4;margin:14mm 12mm 14mm 12mm}*{box-sizing:border-box;margin:0;padding:0}body{font-family:Georgia,serif;font-size:10pt;color:#1a1a2e;line-height:1.5}h1.name{font-size:21pt;font-weight:700;color:#16213e;border-bottom:3px solid #0f3460;padding-bottom:4px;margin-bottom:2px}p.contact{font-size:8.5pt;color:#555;margin-bottom:8px;font-family:Arial,sans-serif}hr{border:none;border-top:1.5px solid #0f3460;margin:7px 0}h2.section-title{font-size:10.5pt;font-weight:700;color:#0f3460;text-transform:uppercase;letter-spacing:1.2px;margin:10px 0 4px 0;border-bottom:1px solid #e0e0e0;padding-bottom:2px}h3.job-title{font-size:10pt;font-weight:700;color:#16213e;margin:7px 0 1px 0}span.date{font-size:8.5pt;color:#666;font-style:italic;display:block;margin-bottom:2px}ul{margin:2px 0 6px 15px}li{margin-bottom:2px;font-size:9.5pt}strong{color:#0f3460}p{margin-bottom:4px;font-size:9.5pt}';
const fullHtml = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><style>' + css + '</style></head><body>' + bodyHtml + '<div style="position:fixed;bottom:5mm;right:12mm;font-size:7.5pt;color:#bbb;">Resume \u2013 ' + candidateName + ' \u2013 ' + company + '</div></body></html>';
return [{ json: { company, jobTitle, rowNumber, candidateName, fileName, rawMarkdown: md, htmlContent: fullHtml } }];

