const bodyHtml = mdToHtml(md);
const css = '@page{size:A4;margin:20mm 18mm 20mm 18mm}*{box-sizing:border-box;margin:0;padding:0}body{font-family:Georgia,serif;font-size:11pt;color:#1a1a2e;line-height:1.7}h1.doc-title{font-size:18pt;color:#0f3460;border-bottom:2px solid #0f3460;padding-bottom:6px;margin-bottom:12px}hr{border:none;border-top:1px solid #ccc;margin:10px 0}strong{color:#0f3460}ul{margin:5px 0 8px 16px}li{margin-bottom:3px}p{margin-bottom:8px}';
