const item = $('Filter: To Be Reviewed').item.json;
const company = (item['Company'] || '').trim();
const jobTitle = (item['Position - Title'] || '').trim();
const jobDesc = (item['Position - Description'] || '').trim();
const rowNumber = item['row_number'] || item['rowNumber'] || 2;

let resumeMarkdown = 'NOT AVAILABLE';
try {
  const drafts = $('Fetch Resume for Review').all()
    .filter(d => d.json && d.json.generated_markdown && !d.json.error)
    .sort((a, b) => new Date(b.json.created_at) - new Date(a.json.created_at));
  if (drafts.length > 0) resumeMarkdown = drafts[0].json.generated_markdown;
} catch(e) {}

let clMarkdown = 'NOT AVAILABLE';
try {
  const clDrafts = $('Fetch CL for Review').all()
    .filter(d => d.json && d.json.generated_markdown && !d.json.error)
    .sort((a, b) => new Date(b.json.created_at) - new Date(a.json.created_at));
  if (clDrafts.length > 0) clMarkdown = clDrafts[0].json.generated_markdown;
} catch(e) {}

const promptText = 'You are a strict QA Reviewer for job application documents.\n\n'
  + 'Job Title: ' + jobTitle + '\nCompany: ' + company + '\n\n'
  + 'JOB DESCRIPTION:\n' + jobDesc + '\n\n'
  + 'RESUME TO REVIEW:\n---\n' + resumeMarkdown + '\n---\n\n'
  + 'COVER LETTER TO REVIEW:\n---\n' + clMarkdown + '\n---\n\n'
  + 'Review both documents carefully. Check:\n'
  + '1. ATS-friendliness — keywords from the JD are present, no tables for skills\n'
  + '2. Resume fits on one page (concise, no padding)\n'
  + '3. No placeholder text like [placeholder] anywhere\n'
  + '4. Factual consistency between resume and cover letter\n'
  + '5. Strong, quantified experience bullets\n'
  + '6. Cover letter references the specific role and company correctly\n'
  + '7. Professional tone throughout\n\n'
  + 'Return your verdict as VALID JSON ONLY — no other text:\n'
  + '{ "verdict": "LGTM" or "Resume rework" or "CL rework" or "Both rework", "notes": "Brief explanation or All good if LGTM" }';

return [{ json: { company, jobTitle, jobDesc, rowNumber, resumeMarkdown, clMarkdown, promptText } }];

const raw = $json.text || '{}';
const rowNumber = $('Prepare Reviewer Inputs').item.json.rowNumber;
let verdict = 'To be reviewed';
let notes = '';
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    verdict = parsed.verdict || 'To be reviewed';
    notes = parsed.notes || '';
  }
} catch(e) {
  notes = 'Reviewer could not parse response: ' + raw.substring(0, 300);
}
return [{ json: { verdict, notes, rowNumber } }];
